//! Engine-backed product fields (E4).
//!
//! These are the product fields for worlds generated by `daena-worldgen`.
//! They keep the product names and units where the engine has the same
//! physical quantity and omit every field the engine does not model. The
//! legacy types in `climate` and `hydrology` stay for consumers that move in
//! E5-E7; E8 deletes them.

use std::collections::{BTreeMap, VecDeque};

use daena_worldgen as worldgen;
use rayon::prelude::*;

use crate::contours;
use crate::planetary::PlanetaryConfiguration;
use crate::{Grid, PhysicalError, PhysicalErrorCode, PhysicalField, Segment, MAX_GEOJSON_FEATURES};

pub use crate::climate::CLIMATE_DERIVATION_VERSION;
pub use crate::hydrology::HYDROLOGY_DERIVATION_VERSION;
pub use worldgen::Biome;

pub const BIOME_CLASS_COUNT: usize = 26;
const MAX_WIND_MILLI: i32 = 400_000;
const GROWING_SEASON_CENTI_C: f64 = 500.0;
const DESERT_PRECIPITATION_MM: f64 = 250.0;
const FOREST_PRECIPITATION_MM: f64 = 500.0;
const MIN_SHELF_DEPTH_MM: i32 = 200_000;
const BATHYMETRY_CONTOURS_MM: [i32; 3] = [100_000, 250_000, 500_000];
const MAGNITUDE_FIVE_TO_FOUR: f64 = 7.943_282_347_242_816;

/// Product M >= 4 annual rate in nano-units for one raster cell.
///
/// The engine publishes M >= 5 per km² per year. Gutenberg–Richter with
/// `b = 0.9` gives `rate(M >= 4) = rate(M >= 5) · 10^0.9` per km²; this
/// multiplies by the cell area in m². Raster products use the view cell area;
/// point and event consumers use the canonical cube cell area.
pub fn earthquake_rate_nano(rate_m5_km2: f32, cell_area_m2: f64) -> u64 {
    (f64::from(rate_m5_km2)
        * (cell_area_m2 / 1_000_000.0)
        * MAGNITUDE_FIVE_TO_FOUR
        * 1_000_000_000.0)
        .round()
        .clamp(0.0, u64::MAX as f64) as u64
}

/// Convert degrees Celsius to centi-degrees.
pub fn centi_celsius(value: f32) -> i32 {
    clamped_i32(f64::from(value) * 100.0)
}

/// Convert millimetres to whole millimetres.
pub fn millimetres(value: f32) -> u32 {
    clamped_u32(f64::from(value))
}

/// Convert a metres-per-second or other SI value to milli-units.
pub fn milli_units(value: f64) -> i32 {
    clamped_i32(value * 1000.0)
}

/// Convert a `[0, 1]` fraction to parts per million.
pub fn fraction_ppm(value: f64) -> u32 {
    clamped_u32(value.clamp(0.0, 1.0) * 1_000_000.0)
}

/// Convert a bounded `u8` potential to parts per million.
pub fn hazard_ppm(value: u8) -> u32 {
    u32::from(value) * 1_000_000 / 255
}

/// Bounded presentation rate per million years from a nano annual rate.
pub fn rate_per_million_years_ppm(nano_per_year: u64) -> u32 {
    ((u128::from(nano_per_year) * 1_000_000) / 1_000_000_000).min(1_000_000) as u32
}

