fn clamped_u32(value: f64) -> u32 {
    value.round().clamp(0.0, f64::from(u32::MAX)) as u32
}

fn clamped_i32(value: f64) -> i32 {
    value
        .round()
        .clamp(f64::from(i32::MIN), f64::from(i32::MAX)) as i32
}

fn direction_from_lat_lon(lat_deg: f64, lon_deg: f64) -> [f64; 3] {
    let lat = lat_deg.to_radians();
    let lon = lon_deg.to_radians();
    let cos_lat = lat.cos();
    [cos_lat * lon.cos(), cos_lat * lon.sin(), lat.sin()]
}

fn dot3(first: [f64; 3], second: [f64; 3]) -> f64 {
    first[0] * second[0] + first[1] * second[1] + first[2] * second[2]
}

fn wind_at(world: &worldgen::World, direction: [f64; 3], month: usize) -> (i32, i32) {
    let field = &world.climate_field;
    let grid = &field.grid;
    let n = grid.cell_count();
    let base = month * 3 * n;
    let x = grid.sample_bilinear(&field.wind[base..base + n], direction);
    let y = grid.sample_bilinear(&field.wind[base + n..base + 2 * n], direction);
    let z = grid.sample_bilinear(&field.wind[base + 2 * n..base + 3 * n], direction);
    let lat = direction[2].clamp(-1.0, 1.0).asin();
    let lon = direction[1].atan2(direction[0]);
    let east = [-lon.sin(), lon.cos(), 0.0];
    let north = [-lat.sin() * lon.cos(), -lat.sin() * lon.sin(), lat.cos()];
    (
        milli_units(dot3([f64::from(x), f64::from(y), f64::from(z)], east))
            .clamp(-MAX_WIND_MILLI, MAX_WIND_MILLI),
        milli_units(dot3([f64::from(x), f64::from(y), f64::from(z)], north))
            .clamp(-MAX_WIND_MILLI, MAX_WIND_MILLI),
    )
}

/// Build the explicit equirectangular view, checking cancellation between row
/// batches. Class and id fields use nearest sampling; continuous fields use
/// bilinear sampling.
pub(crate) fn build_view_raster(
    world: &worldgen::World,
    width: u32,
    height: u32,
    cancelled: &(dyn Fn() -> bool + Sync),
) -> Result<ViewRaster, PhysicalError> {
    let grid = Grid::new(width, height, world.settings.radius_m.round() as u64)
        .map_err(PhysicalError::InvalidSettings)?;
    let count = grid.sample_count();
    let elevation_m = world
        .equirect_elevation_with_cancel(width, height, cancelled)
        .map_err(|error| map_engine_error(error, false))?;
    let elevations_mm = elevation_m
        .iter()
        .map(|value| worldgen::elevation_mm_from_m(*value))
        .collect::<Vec<_>>();
    let mut pixels = vec![Pixel::default(); count];
    let batch_rows = (height as usize / 16).max(1);
    let coarse = &world.climate_field.grid;
    let phi_h = world.climate_field.phi_h_deg;
    let phi_f = world.climate_field.phi_f_deg;
    for start in (0..height as usize).step_by(batch_rows) {
        if cancelled() {
            return Err(PhysicalError::Cancelled);
        }
        let end = (start + batch_rows).min(height as usize);
        pixels[start * width as usize..end * width as usize]
            .par_chunks_mut(width as usize)
            .enumerate()
            .for_each(|(local_row, row_out)| {
                let row = (start + local_row) as u32;
                let lat = -90.0 + 180.0 * (f64::from(row) + 0.5) / f64::from(height);
                let lat_abs = lat.abs();
                let band = if lat_abs <= phi_h {
                    0
                } else if lat_abs <= phi_f {
                    1
                } else {
                    2
                };
                for (col, pixel) in row_out.iter_mut().enumerate() {
                    let lon = -180.0 + 360.0 * (col as f64 + 0.5) / f64::from(width);
                    let direction = direction_from_lat_lon(lat, lon);
                    let source = world.grid.cell_at(direction);
                    let sample = |field: &[f32]| world.grid.sample_bilinear(field, direction);
                    let summer =
                        world.climate_month_at_point(lat, lon, worldgen::NH_SUMMER_SOLSTICE);
                    let winter =
                        world.climate_month_at_point(lat, lon, worldgen::NH_WINTER_SOLSTICE);
                    let annual_wind = (0..12)
                        .map(|month| wind_at(world, direction, month))
                        .fold((0i64, 0i64), |sum, value| {
                            (sum.0 + i64::from(value.0), sum.1 + i64::from(value.1))
                        });
                    let summer_wind = wind_at(world, direction, worldgen::NH_SUMMER_SOLSTICE);
                    let winter_wind = wind_at(world, direction, worldgen::NH_WINTER_SOLSTICE);
                    *pixel = Pixel {
                        temperature: sample(&world.climate.t_annual_c),
                        summer_temperature: summer.0,
                        winter_temperature: winter.0,
                        precipitation: sample(&world.climate.p_annual_mm),
                        summer_precipitation: summer.1,
                        winter_precipitation: winter.1,
                        runoff: sample(&world.climate.runoff_mm),
                        pet: sample(&world.climate.pet_annual_mm),
                        maritime: coarse.sample_bilinear(&world.climate_field.maritime, direction),
                        wind_east: clamped_i32(annual_wind.0 as f64 / 12.0),
                        wind_north: clamped_i32(annual_wind.1 as f64 / 12.0),
                        summer_wind_east: summer_wind.0,
                        summer_wind_north: summer_wind.1,
                        winter_wind_east: winter_wind.0,
                        winter_wind_north: winter_wind.1,
                        wind_band: band,
                        biome: world.biome[source as usize],
                        lake_id: world.hydrology.lake_id[source as usize],
                        ice: world.hydrology.ice_cover[source as usize],
                        quake_rate: sample(&world.hazards.quake_rate_km2),
                        quake: world.hazards.quake_hazard[source as usize],
                        volcanic: world.hazards.volcanic_hazard[source as usize],
                        drought: world.hazards.drought[source as usize],
                        heat: world.hazards.heat_wave[source as usize],
                        rain: world.hazards.extreme_rain[source as usize],
                        flood: world.hazards.flood[source as usize],
                        storm_genesis: coarse
                            .sample_bilinear(&world.hazards.storms.genesis_km2, direction),
                        storm_track: coarse
                            .sample_bilinear(&world.hazards.storms.track_km2, direction),
                        storm_intensity: coarse
                            .sample_bilinear(&world.hazards.storms.intensity, direction),
                        source_cell: source,
                    };
                }
            });
    }
    let mut raster = ViewRaster {
        grid,
        elevations_mm,
        ocean: Vec::with_capacity(count),
        temperature_centi_c: Vec::with_capacity(count),
        temperature_nh_summer_centi_c: Vec::with_capacity(count),
        temperature_nh_winter_centi_c: Vec::with_capacity(count),
        precipitation_mm_per_year: Vec::with_capacity(count),
        precipitation_nh_summer_mm: Vec::with_capacity(count),
        precipitation_nh_winter_mm: Vec::with_capacity(count),
        runoff_mm_per_year: Vec::with_capacity(count),
        pet_mm_per_year: Vec::with_capacity(count),
        maritime_factor_ppm: Vec::with_capacity(count),
        wind_east_milli: Vec::with_capacity(count),
        wind_north_milli: Vec::with_capacity(count),
        wind_east_nh_summer_milli: Vec::with_capacity(count),
        wind_north_nh_summer_milli: Vec::with_capacity(count),
        wind_east_nh_winter_milli: Vec::with_capacity(count),
        wind_north_nh_winter_milli: Vec::with_capacity(count),
        wind_band: Vec::with_capacity(count),
        biome_class: Vec::with_capacity(count),
        lake_id: Vec::with_capacity(count),
        ice_cover: Vec::with_capacity(count),
        source_cell: Vec::with_capacity(count),
        quake_rate_km2: Vec::with_capacity(count),
        quake_hazard: Vec::with_capacity(count),
        volcanic_hazard: Vec::with_capacity(count),
        drought: Vec::with_capacity(count),
        heat_wave: Vec::with_capacity(count),
        extreme_rain: Vec::with_capacity(count),
        flood: Vec::with_capacity(count),
        storm_genesis_km2: Vec::with_capacity(count),
        storm_track_km2: Vec::with_capacity(count),
        storm_intensity: Vec::with_capacity(count),
    };
    for pixel in pixels {
        let source = pixel.source_cell as usize;
        raster.ocean.push(world.ocean[source] == 1);
        raster
            .temperature_centi_c
            .push(centi_celsius(pixel.temperature));
        raster
            .temperature_nh_summer_centi_c
            .push(centi_celsius(pixel.summer_temperature));
        raster
            .temperature_nh_winter_centi_c
            .push(centi_celsius(pixel.winter_temperature));
        raster
            .precipitation_mm_per_year
            .push(millimetres(pixel.precipitation));
        raster
            .precipitation_nh_summer_mm
            .push(millimetres(pixel.summer_precipitation));
        raster
            .precipitation_nh_winter_mm
            .push(millimetres(pixel.winter_precipitation));
        raster.runoff_mm_per_year.push(millimetres(pixel.runoff));
        raster.pet_mm_per_year.push(millimetres(pixel.pet));
        raster
            .maritime_factor_ppm
            .push(fraction_ppm(f64::from(pixel.maritime)));
        raster.wind_east_milli.push(pixel.wind_east);
        raster.wind_north_milli.push(pixel.wind_north);
        raster
            .wind_east_nh_summer_milli
            .push(pixel.summer_wind_east);
        raster
            .wind_north_nh_summer_milli
            .push(pixel.summer_wind_north);
        raster
            .wind_east_nh_winter_milli
            .push(pixel.winter_wind_east);
        raster
            .wind_north_nh_winter_milli
            .push(pixel.winter_wind_north);
        raster.wind_band.push(pixel.wind_band);
        raster
            .biome_class
            .push(u32::from(pixel.biome).min((BIOME_CLASS_COUNT - 1) as u32));
        raster.lake_id.push(pixel.lake_id);
        raster.ice_cover.push(pixel.ice);
        raster.source_cell.push(pixel.source_cell);
        raster.quake_rate_km2.push(pixel.quake_rate);
        raster.quake_hazard.push(pixel.quake);
        raster.volcanic_hazard.push(pixel.volcanic);
        raster.drought.push(pixel.drought);
        raster.heat_wave.push(pixel.heat);
        raster.extreme_rain.push(pixel.rain);
        raster.flood.push(pixel.flood);
        raster.storm_genesis_km2.push(pixel.storm_genesis);
        raster.storm_track_km2.push(pixel.storm_track);
        raster.storm_intensity.push(pixel.storm_intensity);
    }
    Ok(raster)
}

pub(crate) fn build_climate(
    world: &worldgen::World,
    raster: &ViewRaster,
    planetary: PlanetaryConfiguration,
) -> Result<ClimateField, PhysicalError> {
    let grid = raster.grid;
    let aridity = raster
        .pet_mm_per_year
        .iter()
        .enumerate()
        .map(|(cell, pet)| {
            if raster.ocean[cell] || *pet == 0 {
                0
            } else {
                fraction_ppm(
                    1.0 - f64::from(raster.precipitation_mm_per_year[cell]) / f64::from(*pet),
                )
            }
        })
        .collect::<Vec<_>>();
    let annual_divergence = divergence(grid, &raster.wind_east_milli, &raster.wind_north_milli);
    let summer_divergence = divergence(
        grid,
        &raster.wind_east_nh_summer_milli,
        &raster.wind_north_nh_summer_milli,
    );
    let winter_divergence = divergence(
        grid,
        &raster.wind_east_nh_winter_milli,
        &raster.wind_north_nh_winter_milli,
    );
    let (storm_suitability, storm_track) = presentation_indices(raster);
    let runoff_volume = raster
        .runoff_mm_per_year
        .iter()
        .enumerate()
        .map(|(cell, millimetres)| {
            (f64::from(*millimetres) / 1000.0 * grid.cell_area(grid.row_col(cell).0)).round() as u64
        })
        .collect::<Vec<_>>();
    let metrics = climate_metrics(
        world,
        raster,
        &aridity,
        &storm_suitability,
        &storm_track,
        &annual_divergence,
    );
    let field = ClimateField {
        grid,
        derivation_version: CLIMATE_DERIVATION_VERSION,
        planetary,
        temperature_centi_c: raster.temperature_centi_c.clone(),
        temperature_nh_summer_centi_c: raster.temperature_nh_summer_centi_c.clone(),
        temperature_nh_winter_centi_c: raster.temperature_nh_winter_centi_c.clone(),
        precipitation_mm_per_year: raster.precipitation_mm_per_year.clone(),
        runoff_mm_per_year: raster.runoff_mm_per_year.clone(),
        runoff_volume_m3_per_year: runoff_volume,
        maritime_factor_ppm: raster.maritime_factor_ppm.clone(),
        wind_east_milli: raster.wind_east_milli.clone(),
        wind_north_milli: raster.wind_north_milli.clone(),
        wind_east_nh_summer_milli: raster.wind_east_nh_summer_milli.clone(),
        wind_north_nh_summer_milli: raster.wind_north_nh_summer_milli.clone(),
        wind_east_nh_winter_milli: raster.wind_east_nh_winter_milli.clone(),
        wind_north_nh_winter_milli: raster.wind_north_nh_winter_milli.clone(),
        wind_divergence_nano_per_s: annual_divergence,
        wind_divergence_nh_summer_nano_per_s: summer_divergence,
        wind_divergence_nh_winter_nano_per_s: winter_divergence,
        wind_band: raster.wind_band.clone(),
        wind_band_nh_summer: raster.wind_band.clone(),
        wind_band_nh_winter: raster.wind_band.clone(),
        aridity_ppm: aridity,
        precipitation_nh_summer_mm: raster.precipitation_nh_summer_mm.clone(),
        precipitation_nh_winter_mm: raster.precipitation_nh_winter_mm.clone(),
        biome_class: raster.biome_class.clone(),
        storm_suitability_ppm: storm_suitability,
        storm_track_ppm: storm_track,
        storm_intensity_ppm: raster
            .storm_intensity
            .iter()
            .map(|value| fraction_ppm(f64::from(*value)))
            .collect(),
        metrics,
    };
    field.validate()?;
    Ok(field)
}

fn presentation_indices(raster: &ViewRaster) -> (Vec<u32>, Vec<u32>) {
    let genesis_max = raster
        .storm_genesis_km2
        .iter()
        .copied()
        .fold(0.0f32, f32::max);
    let track_max = raster
        .storm_track_km2
        .iter()
        .copied()
        .fold(0.0f32, f32::max);
    let genesis = raster
        .storm_genesis_km2
        .iter()
        .map(|value| {
            if genesis_max > 0.0 {
                (f64::from(*value) / f64::from(genesis_max) * 1_000_000.0).round() as u32
            } else {
                0
            }
        })
        .collect();
    let track = raster
        .storm_track_km2
        .iter()
        .map(|value| {
            if track_max > 0.0 {
                (f64::from(*value) / f64::from(track_max) * 1_000_000.0).round() as u32
            } else {
                0
            }
        })
        .collect();
    (genesis, track)
}

fn divergence(grid: Grid, east: &[i32], north: &[i32]) -> Vec<i32> {
    let width = grid.width as usize;
    let height = grid.height as usize;
    let radius = grid.radius_metres as f64;
    let delta_lon = std::f64::consts::TAU / f64::from(grid.width);
    let delta_lat = std::f64::consts::PI / f64::from(grid.height);
    let latitude = |row: usize| {
        -std::f64::consts::FRAC_PI_2
            + std::f64::consts::PI * (row as f64 + 0.5) / f64::from(grid.height)
    };
    let mut out = vec![0i32; east.len()];
    for row in 0..height {
        let lat = latitude(row);
        let cos_lat = lat.cos().max(1.0e-3);
        let up_row = row.saturating_sub(1);
        let down_row = (row + 1).min(height - 1);
        let cos_up = latitude(up_row).cos().max(1.0e-3);
        let cos_down = latitude(down_row).cos().max(1.0e-3);
        for col in 0..width {
            let index = row * width + col;
            let left = row * width + (col + width - 1) % width;
            let right = row * width + (col + 1) % width;
            let down = down_row * width + col;
            let up = up_row * width + col;
            let du = (f64::from(east[right]) - f64::from(east[left])) / 1000.0;
            let dv_cos = f64::from(north[down]) * cos_down - f64::from(north[up]) * cos_up;
            let divergence =
                (du / (2.0 * delta_lon) + dv_cos / 1000.0 / (2.0 * delta_lat)) / (radius * cos_lat);
            out[index] = clamped_i32(divergence * 1_000_000_000.0);
        }
    }
    out
}

fn sinusoid_above_fraction(first: f64, second: f64, threshold: f64) -> f64 {
    let mean = 0.5 * (first + second);
    let amplitude = 0.5 * (first - second).abs();
    if amplitude <= 1e-9 {
        return if mean > threshold { 1.0 } else { 0.0 };
    }
    let k = (threshold - mean) / amplitude;
    if k >= 1.0 {
        0.0
    } else if k <= -1.0 {
        1.0
    } else {
        0.5 - k.asin() / std::f64::consts::PI
    }
}

fn climate_metrics(
    world: &worldgen::World,
    raster: &ViewRaster,
    aridity: &[u32],
    storm_suitability: &[u32],
    storm_track: &[u32],
    divergence: &[i32],
) -> ClimateMetrics {
    let grid = raster.grid;
    let count = grid.sample_count();
    let mut metrics = ClimateMetrics::default();
    let mut total_area = 0.0;
    let mut land_area = 0.0;
    let mut ocean_area = 0.0;
    let mut temperature_sum = 0.0;
    let mut precipitation_sum = 0.0;
    let mut runoff_sum = 0.0;
    let mut precipitation_volume = 0u64;
    let mut runoff_volume = 0u64;
    let mut wettest = 0u32;
    let mut driest_land = u32::MAX;
    let mut range_sum = 0.0;
    let mut min_seasonal = i32::MAX;
    let mut max_seasonal = i32::MIN;
    let mut permanent_area = 0.0;
    let mut seasonal_area = 0.0;
    let mut wind_speed_sum = 0.0;
    let mut easterly_area = 0.0;
    let mut converging_area = 0.0;
    let mut aridity_sum = 0.0;
    let mut seasonal_precipitation_range = 0.0;
    let mut biome_area = [0.0f64; BIOME_CLASS_COUNT];
    let mut ocean_suitability = 0.0;
    let mut prone_area = 0.0;
    let mut intensity_sum = 0.0;
    let mut land_track = 0.0;
    let mut drought = 0.0;
    let mut heat = 0.0;
    let mut rain = 0.0;
    let mut growing = 0.0;
    let mut dry_season = 0.0;
    let mut wet_season = 0.0;
    for cell in 0..count {
        let area = grid.cell_area(grid.row_col(cell).0);
        total_area += area;
        let ocean = raster.ocean[cell];
        temperature_sum += f64::from(raster.temperature_centi_c[cell]) * area;
        precipitation_sum += f64::from(raster.precipitation_mm_per_year[cell]) * area;
        runoff_sum += f64::from(raster.runoff_mm_per_year[cell]) * area;
        precipitation_volume +=
            (f64::from(raster.precipitation_mm_per_year[cell]) / 1000.0 * area).round() as u64;
        runoff_volume +=
            (f64::from(raster.runoff_mm_per_year[cell]) / 1000.0 * area).round() as u64;
        wettest = wettest.max(raster.precipitation_mm_per_year[cell]);
        range_sum += f64::from(
            (raster.temperature_nh_summer_centi_c[cell]
                - raster.temperature_nh_winter_centi_c[cell])
                .unsigned_abs(),
        ) * area;
        min_seasonal = min_seasonal.min(raster.temperature_nh_winter_centi_c[cell]);
        max_seasonal = max_seasonal.max(raster.temperature_nh_summer_centi_c[cell]);
        wind_speed_sum += f64::from(raster.wind_east_milli[cell])
            .hypot(f64::from(raster.wind_north_milli[cell]))
            * area;
        if raster.wind_east_milli[cell] < 0 {
            easterly_area += area;
        }
        if divergence[cell] < 0 {
            converging_area += area;
        }
        seasonal_precipitation_range += f64::from(
            raster.precipitation_nh_summer_mm[cell]
                .abs_diff(raster.precipitation_nh_winter_mm[cell]),
        ) * area;
        let biome = raster.biome_class[cell] as usize;
        biome_area[biome] += area;
        if ocean {
            ocean_area += area;
            ocean_suitability += f64::from(storm_suitability[cell]) * area;
            if storm_suitability[cell] > 500_000 {
                prone_area += area;
            }
            intensity_sum += f64::from(raster.storm_intensity[cell]) * area;
        } else {
            land_area += area;
            driest_land = driest_land.min(raster.precipitation_mm_per_year[cell]);
            aridity_sum += f64::from(aridity[cell]) * area;
            if raster.temperature_nh_summer_centi_c[cell] < 0 {
                permanent_area += area;
            } else if raster.temperature_nh_winter_centi_c[cell] < 0 {
                seasonal_area += area;
            }
            land_track += f64::from(storm_track[cell]) * area;
            drought += f64::from(u32::from(raster.drought[cell]) * 1_000_000 / 255) * area;
            growing += sinusoid_above_fraction(
                f64::from(raster.temperature_nh_summer_centi_c[cell]),
                f64::from(raster.temperature_nh_winter_centi_c[cell]),
                GROWING_SEASON_CENTI_C,
            ) * area;
            dry_season +=
                (1.0 - sinusoid_above_fraction(
                    f64::from(raster.precipitation_nh_summer_mm[cell]),
                    f64::from(raster.precipitation_nh_winter_mm[cell]),
                    DESERT_PRECIPITATION_MM,
                )) * area;
            wet_season += sinusoid_above_fraction(
                f64::from(raster.precipitation_nh_summer_mm[cell]),
                f64::from(raster.precipitation_nh_winter_mm[cell]),
                FOREST_PRECIPITATION_MM,
            ) * area;
        }
        heat += f64::from(u32::from(raster.heat_wave[cell]) * 1_000_000 / 255) * area;
        rain += f64::from(u32::from(raster.extreme_rain[cell]) * 1_000_000 / 255) * area;
    }
    let total_area = total_area.max(f64::EPSILON);
    let land_area = land_area.max(f64::EPSILON);
    let ocean_area = ocean_area.max(f64::EPSILON);
    let storms_per_year = world
        .hazards
        .storms
        .genesis_km2
        .iter()
        .enumerate()
        .map(|(cell, genesis)| {
            f64::from(*genesis) * world.climate_field.grid.area_m2(cell as u32) / 1_000_000.0
        })
        .sum::<f64>();
    metrics.precipitation_volume_m3_per_year = precipitation_volume;
    metrics.runoff_volume_m3_per_year = runoff_volume;
    metrics.mean_temperature_centi_c = (temperature_sum / total_area).round() as i32;
    metrics.minimum_temperature_centi_c = raster
        .temperature_centi_c
        .iter()
        .copied()
        .min()
        .unwrap_or(0);
    metrics.maximum_temperature_centi_c = raster
        .temperature_centi_c
        .iter()
        .copied()
        .max()
        .unwrap_or(0);
    metrics.mean_precipitation_mm_per_year = (precipitation_sum / total_area).round() as u32;
    metrics.mean_runoff_mm_per_year = (runoff_sum / total_area).round() as u32;
    metrics.wettest_cell_precipitation_mm_per_year = wettest;
    metrics.driest_land_cell_precipitation_mm_per_year = if driest_land == u32::MAX {
        0
    } else {
        driest_land
    };
    metrics.climate_spinup_years = world.climate_field.spinup_years;
    metrics.mean_seasonal_range_centi_c = (range_sum / total_area).round() as u32;
    metrics.minimum_seasonal_temperature_centi_c = min_seasonal;
    metrics.maximum_seasonal_temperature_centi_c = max_seasonal;
    metrics.permanently_frozen_land_ppm = (permanent_area / land_area * 1_000_000.0).round() as u32;
    metrics.seasonally_frozen_land_ppm = (seasonal_area / land_area * 1_000_000.0).round() as u32;
    metrics.mean_wind_speed_milli = (wind_speed_sum / total_area).round() as u32;
    metrics.itcz_latitude_milli_deg = if world.climate_field.itcz_lat_deg.is_empty() {
        0
    } else {
        (world
            .climate_field
            .itcz_lat_deg
            .iter()
            .map(|value| f64::from(*value))
            .sum::<f64>()
            / world.climate_field.itcz_lat_deg.len() as f64
            * 1000.0)
            .round() as i32
    };
    metrics.easterly_cell_ppm = (easterly_area / total_area * 1_000_000.0).round() as u32;
    metrics.converging_cell_ppm = (converging_area / total_area * 1_000_000.0).round() as u32;
    metrics.mean_land_aridity_ppm = (aridity_sum / land_area).round() as u32;
    metrics.mean_seasonal_precipitation_range_mm =
        (seasonal_precipitation_range / total_area).round() as u32;
    metrics.dominant_land_biome = biome_area
        .iter()
        .enumerate()
        .max_by(|first, second| first.1.total_cmp(second.1))
        .map(|(index, _)| index as u32)
        .unwrap_or(0);
    metrics.mean_ocean_storm_suitability_ppm = (ocean_suitability / ocean_area).round() as u32;
    metrics.storm_prone_ocean_ppm = (prone_area / ocean_area * 1_000_000.0).round() as u32;
    metrics.mean_storm_intensity_ppm = (intensity_sum / ocean_area * 1_000_000.0).round() as u32;
    metrics.mean_land_storm_track_ppm = (land_track / land_area).round() as u32;
    metrics.expected_storms_per_year_milli = (storms_per_year * 1000.0).round() as u32;
    metrics.mean_land_drought_potential_ppm = (drought / land_area).round() as u32;
    metrics.mean_heat_wave_potential_ppm = (heat / total_area).round() as u32;
    metrics.mean_extreme_rainfall_potential_ppm = (rain / total_area).round() as u32;
    metrics.mean_land_growing_season_ppm = (growing / land_area * 1_000_000.0).round() as u32;
    metrics.mean_land_dry_season_ppm = (dry_season / land_area * 1_000_000.0).round() as u32;
    metrics.mean_land_wet_season_ppm = (wet_season / land_area * 1_000_000.0).round() as u32;
    metrics
}

pub(crate) fn build_hazards(
    world: &worldgen::World,
    raster: &ViewRaster,
    cancelled: &(dyn Fn() -> bool + Sync),
) -> Result<HazardField, PhysicalError> {
    let grid = raster.grid;
    let count = grid.sample_count();
    let quake_hazard = raster
        .quake_hazard
        .iter()
        .map(|value| hazard_ppm(*value))
        .collect::<Vec<_>>();
    let volcanic_hazard = raster
        .volcanic_hazard
        .iter()
        .map(|value| hazard_ppm(*value))
        .collect::<Vec<_>>();
    let mut quake_rate = Vec::with_capacity(count);
    let mut quake_ppm = Vec::with_capacity(count);
    for (cell, rate) in raster.quake_rate_km2.iter().enumerate() {
        let annual = earthquake_rate_nano(*rate, grid.cell_area(grid.row_col(cell).0));
        quake_rate.push(annual);
        quake_ppm.push(rate_per_million_years_ppm(annual));
    }
    let mut eruption_rate = vec![0u64; count];
    for source in &world.hazards.volcanic_sources {
        let cell = view_cell_for_source(world, grid, source.cell);
        eruption_rate[cell] = eruption_rate[cell]
            .saturating_add((f64::from(source.eruptions_per_yr) * 1_000_000_000.0).round() as u64);
    }
    let eruption_ppm = eruption_rate
        .iter()
        .map(|value| rate_per_million_years_ppm(*value))
        .collect::<Vec<_>>();
    let volcanic_sources = world
        .hazards
        .volcanic_sources
        .iter()
        .map(|source| VolcanicSource {
            stable_id: source.id,
            cell: source.cell,
            origin: match source.origin {
                worldgen::VolcanicOrigin::Hotspot => VolcanicOrigin::Hotspot,
                worldgen::VolcanicOrigin::SubductionArc => VolcanicOrigin::SubductionArc,
                worldgen::VolcanicOrigin::Rift => VolcanicOrigin::Rift,
            },
            activity_class: match source.activity {
                worldgen::VolcanicActivity::Dormant => VolcanicActivity::Dormant,
                worldgen::VolcanicActivity::Moderate => VolcanicActivity::Moderate,
                worldgen::VolcanicActivity::Vigorous => VolcanicActivity::Vigorous,
            },
            eruptions_per_model_year_nano: (f64::from(source.eruptions_per_yr) * 1_000_000_000.0)
                .round() as u64,
        })
        .collect::<Vec<_>>();
    let mean = |values: &[u32]| {
        if values.is_empty() {
            0
        } else {
            (values.iter().map(|value| u64::from(*value)).sum::<u64>() / values.len() as u64) as u32
        }
    };
    let mut earthquake_rate_mass_nano = 0u64;
    for (cell, rate) in world.hazards.quake_rate_km2.iter().enumerate() {
        if cell.is_multiple_of(65_536) && cancelled() {
            return Err(PhysicalError::Cancelled);
        }
        earthquake_rate_mass_nano = earthquake_rate_mass_nano.saturating_add(
            (f64::from(*rate) * world.grid.area_m2(cell as u32) / 1_000_000.0
                * MAGNITUDE_FIVE_TO_FOUR
                * 1_000_000_000.0)
                .round() as u64,
        );
    }
    if cancelled() {
        return Err(PhysicalError::Cancelled);
    }
    let volcanic_rate_mass_nano = volcanic_sources
        .iter()
        .map(|source| source.eruptions_per_model_year_nano)
        .fold(0u64, u64::saturating_add);
    let metrics = HazardMetrics {
        derivation_version: crate::hazards::HAZARD_DERIVATION_VERSION,
        volcanic_source_derivation_version: crate::hazards::VOLCANIC_SOURCE_DERIVATION_VERSION,
        volcanic_source_count: volcanic_sources.len() as u32,
        non_dormant_source_count: volcanic_sources
            .iter()
            .filter(|source| source.activity_class != VolcanicActivity::Dormant)
            .count() as u32,
        earthquake_mean_ppm: mean(&quake_hazard),
        earthquake_max_ppm: quake_hazard.iter().copied().max().unwrap_or(0),
        volcanic_mean_ppm: mean(&volcanic_hazard),
        volcanic_max_ppm: volcanic_hazard.iter().copied().max().unwrap_or(0),
        earthquake_rate_mass_nano,
        volcanic_rate_mass_nano,
    };
    let field = HazardField {
        earthquake_hazard_ppm: quake_hazard,
        volcanic_hazard_ppm: volcanic_hazard,
        earthquake_annual_rate_nano: quake_rate,
        volcanic_annual_rate_nano: eruption_rate,
        earthquake_rate_per_million_years_ppm: quake_ppm,
        eruption_rate_per_million_years_ppm: eruption_ppm,
        volcanic_sources,
        metrics,
    };
    field.validate(grid)?;
    Ok(field)
}

fn view_cell_for_lat_lon(grid: Grid, lat: f64, lon: f64) -> usize {
    let col = ((lon + 180.0) / 360.0 * f64::from(grid.width))
        .floor()
        .clamp(0.0, f64::from(grid.width.saturating_sub(1))) as u32;
    let row = ((lat + 90.0) / 180.0 * f64::from(grid.height))
        .floor()
        .clamp(0.0, f64::from(grid.height.saturating_sub(1))) as u32;
    grid.index(row, col)
}

fn view_cell_for_source(world: &worldgen::World, grid: Grid, cell: u32) -> usize {
    let (lat, lon) = world.cell_lat_lon(cell);
    view_cell_for_lat_lon(grid, lat, lon)
}

fn canonical_roots(
    receiver: &[u32],
    cancelled: &(dyn Fn() -> bool + Sync),
) -> Result<Vec<u32>, PhysicalError> {
    let n = receiver.len();
    let mut roots = vec![u32::MAX; n];
    let mut visited = 0usize;
    for start in 0..n {
        if start.is_multiple_of(65_536) && cancelled() {
            return Err(PhysicalError::Cancelled);
        }
        if roots[start] != u32::MAX {
            continue;
        }
        let mut path = Vec::new();
        let mut cell = start;
        let root = loop {
            visited += 1;
            if visited.is_multiple_of(65_536) && cancelled() {
                return Err(PhysicalError::Cancelled);
            }
            if roots[cell] != u32::MAX {
                break roots[cell];
            }
            let next = receiver[cell] as usize;
            if next == cell || next >= n || path.len() > n {
                roots[cell] = cell as u32;
                break cell as u32;
            }
            path.push(cell);
            cell = next;
        };
        for cell in path {
            roots[cell] = root;
        }
    }
    Ok(roots)
}

fn canonical_islands(
    world: &worldgen::World,
    cancelled: &(dyn Fn() -> bool + Sync),
) -> Result<Vec<u32>, PhysicalError> {
    let n = world.ocean.len();
    let mut ids = vec![u32::MAX; n];
    let mut visited = 0usize;
    for start in 0..n {
        if start.is_multiple_of(65_536) && cancelled() {
            return Err(PhysicalError::Cancelled);
        }
        if world.ocean[start] == 1 || ids[start] != u32::MAX {
            continue;
        }
        let id = start as u32;
        ids[start] = id;
        let mut queue = VecDeque::from([start]);
        while let Some(cell) = queue.pop_front() {
            visited += 1;
            if visited.is_multiple_of(65_536) && cancelled() {
                return Err(PhysicalError::Cancelled);
            }
            for neighbor in world.grid.neighbors(cell as u32) {
                let neighbor = neighbor as usize;
                if neighbor < n && world.ocean[neighbor] == 0 && ids[neighbor] == u32::MAX {
                    ids[neighbor] = id;
                    queue.push_back(neighbor);
                }
            }
        }
    }
    Ok(ids)
}

fn river_order(
    world: &worldgen::World,
    cancelled: &(dyn Fn() -> bool + Sync),
) -> Result<Vec<u16>, PhysicalError> {
    river_strahler_orders(
        &world.hydrology.receiver,
        &world.hydrology.rivers,
        cancelled,
    )
}

pub(crate) fn river_strahler_orders(
    receiver: &[u32],
    rivers: &[worldgen::RiverSegment],
    cancelled: &(dyn Fn() -> bool + Sync),
) -> Result<Vec<u16>, PhysicalError> {
    let n = receiver.len();
    let mut is_river = vec![false; n];
    for river in rivers {
        let skip_end = match river.end {
            worldgen::RiverEnd::Ocean | worldgen::RiverEnd::Lake => 1,
            worldgen::RiverEnd::Confluence => 0,
        };
        if river.cells.len() <= skip_end {
            continue;
        }
        for cell in &river.cells[..river.cells.len() - skip_end] {
            if (*cell as usize) < n {
                is_river[*cell as usize] = true;
            }
        }
    }
    let mut donors = vec![0u32; n];
    for (cell, next) in receiver.iter().enumerate() {
        if !is_river[cell] {
            continue;
        }
        if cell.is_multiple_of(65_536) && cancelled() {
            return Err(PhysicalError::Cancelled);
        }
        let parent = *next as usize;
        if parent != cell && parent < n && is_river[parent] {
            donors[parent] += 1;
        }
    }
    let mut order = vec![0u16; n];
    for cell in 0..n {
        if is_river[cell] {
            order[cell] = 1;
        }
    }
    let mut remaining = donors.clone();
    let mut queue = VecDeque::new();
    for (cell, count) in remaining.iter().enumerate() {
        if is_river[cell] && *count == 0 {
            queue.push_back(cell);
        }
    }
    let mut max_child = vec![0u16; n];
    let mut max_count = vec![0u16; n];
    let mut processed = 0usize;
    while let Some(cell) = queue.pop_front() {
        processed += 1;
        if processed.is_multiple_of(65_536) && cancelled() {
            return Err(PhysicalError::Cancelled);
        }
        let parent = receiver[cell] as usize;
        if parent == cell || parent >= n || !is_river[parent] {
            continue;
        }
        let child_order = order[cell];
        if child_order > max_child[parent] {
            max_child[parent] = child_order;
            max_count[parent] = 1;
        } else if child_order == max_child[parent] {
            max_count[parent] += 1;
        }
        remaining[parent] -= 1;
        if remaining[parent] == 0 {
            order[parent] = if max_count[parent] > 1 {
                max_child[parent].saturating_add(1)
            } else {
                max_child[parent].max(1)
            };
            queue.push_back(parent);
        }
    }
    Ok(order)
}

fn slope_ppm(field: &PhysicalField) -> Vec<u32> {
    let grid = field.grid;
    let width = grid.width as i32;
    let height = grid.height as i32;
    let radius = grid.radius_metres as f64;
    let delta_lon = std::f64::consts::TAU / f64::from(grid.width);
    let delta_lat = std::f64::consts::PI / f64::from(grid.height);
    let mut out = vec![0u32; grid.sample_count()];
    for (cell, slot) in out.iter_mut().enumerate() {
        let (row, col) = grid.row_col(cell);
        let lat = -std::f64::consts::FRAC_PI_2
            + std::f64::consts::PI * (f64::from(row) + 0.5) / f64::from(grid.height);
        let east = grid.index(row, ((col as i32 + 1).rem_euclid(width)) as u32);
        let west = grid.index(row, ((col as i32 - 1).rem_euclid(width)) as u32);
        let north = grid.index(((row as i32 - 1).max(0)) as u32, col);
        let south = grid.index(((row as i32 + 1).min(height - 1)) as u32, col);
        let dx = (2.0 * radius * lat.cos() * delta_lon).max(1.0);
        let dy = (2.0 * radius * delta_lat).max(1.0);
        let dzdx = (f64::from(field.elevations_mm[east]) - f64::from(field.elevations_mm[west]))
            / (2.0 * dx);
        let dzdy = (f64::from(field.elevations_mm[south]) - f64::from(field.elevations_mm[north]))
            / (2.0 * dy);
        // Millimetres per metre times 1000 is micrometres per metre (ppm).
        *slot = (dzdx.hypot(dzdy) * 1_000.0)
            .round()
            .clamp(0.0, f64::from(u32::MAX)) as u32;
    }
    out
}

fn hillshade(field: &PhysicalField, cell: usize) -> u32 {
    let grid = field.grid;
    let (row, col) = grid.row_col(cell);
    let width = grid.width as i32;
    let height = grid.height as i32;
    let sample = |row_offset: i32, col_offset: i32| {
        let sample_row = (row as i32 + row_offset).clamp(0, height - 1) as u32;
        let sample_col = ((col as i32 + col_offset).rem_euclid(width)) as u32;
        f64::from(field.elevations_mm[grid.index(sample_row, sample_col)])
    };
    let z1 = sample(-1, -1);
    let z2 = sample(-1, 0);
    let z3 = sample(-1, 1);
    let z4 = sample(0, -1);
    let z6 = sample(0, 1);
    let z7 = sample(1, -1);
    let z8 = sample(1, 0);
    let z9 = sample(1, 1);
    let cell_metres =
        (std::f64::consts::PI * grid.radius_metres as f64 / f64::from(grid.height.max(1))).max(1.0);
    let dzdx = ((z3 + 2.0 * z6 + z9) - (z1 + 2.0 * z4 + z7)) / (8.0 * cell_metres);
    let dzdy = ((z7 + 2.0 * z8 + z9) - (z1 + 2.0 * z2 + z3)) / (8.0 * cell_metres);
    let slope = dzdx.hypot(dzdy).atan();
    let aspect = (-dzdx).atan2(dzdy);
    let zenith = 45.0_f64.to_radians();
    let azimuth = 315.0_f64.to_radians();
    let illumination = (zenith.cos() * slope.cos()
        + zenith.sin() * slope.sin() * (azimuth - aspect).cos())
    .clamp(0.0, 1.0);
    (illumination * 1_000_000.0).round().clamp(0.0, 1_000_000.0) as u32
}

fn bathymetry_contours(
    field: &PhysicalField,
    ocean: &[bool],
    cancelled: &(dyn Fn() -> bool + Sync),
) -> Result<Vec<Segment>, PhysicalError> {
    let mut scalar = vec![-1i32; field.grid.sample_count()];
    for cell in 0..scalar.len() {
        if ocean[cell] {
            scalar[cell] = field
                .sea_level_mm
                .saturating_sub(field.elevations_mm[cell])
                .max(0);
        }
    }
    let mut segments = Vec::new();
    for threshold in BATHYMETRY_CONTOURS_MM {
        let paths = contours::isolines_at_with_cancel(field.grid, &scalar, threshold, cancelled)?;
        segments.extend(contours::segments_from_paths(&paths));
        if cancelled() {
            return Err(PhysicalError::Cancelled);
        }
    }
    Ok(segments)
}

pub(crate) fn build_hydrology(
    world: &worldgen::World,
    raster: &ViewRaster,
    field: &PhysicalField,
    cancelled: &(dyn Fn() -> bool + Sync),
) -> Result<HydrologyField, PhysicalError> {
    let grid = field.grid;
    let count = grid.sample_count();
    let sea_level = field.sea_level_mm;
    let reference_elevation = |cell: usize| {
        worldgen::elevation_mm_from_m(world.elevation_m[cell]).saturating_add(sea_level)
    };
    let roots = canonical_roots(&world.hydrology.receiver, cancelled)?;
    let islands = canonical_islands(world, cancelled)?;
    let lake_cells = raster
        .lake_id
        .iter()
        .map(|id| *id != worldgen::NONE)
        .collect::<Vec<_>>();
    let mut basin_by_cell = vec![u32::MAX; count];
    let mut lake_levels = vec![sea_level; count];
    let mut lake_level_by_id: BTreeMap<u32, i32> = BTreeMap::new();
    for lake in &world.hydrology.lakes {
        lake_level_by_id.insert(lake.id, (lake.level_m * 1000.0).round() as i32 + sea_level);
    }
    let mut lake_counts: BTreeMap<u32, u32> = BTreeMap::new();
    for id in &world.hydrology.lake_id {
        if *id != worldgen::NONE {
            *lake_counts.entry(*id).or_default() += 1;
        }
    }
    for cell in 0..count {
        if lake_cells[cell] {
            basin_by_cell[cell] = raster.lake_id[cell];
            lake_levels[cell] = lake_level_by_id
                .get(&raster.lake_id[cell])
                .copied()
                .unwrap_or(sea_level);
        }
    }
    let mut basins = Vec::with_capacity(world.hydrology.lakes.len());
    for lake in &world.hydrology.lakes {
        let level_mm = (lake.level_m * 1000.0).round() as i32 + sea_level;
        let (status, spill_elevation) = match lake.kind {
            worldgen::LakeKind::Fresh if lake.outflow_m3 > 0.0 => {
                (BasinStatus::Overflowing, Some(level_mm))
            }
            worldgen::LakeKind::Fresh => (BasinStatus::Active, Some(level_mm)),
            worldgen::LakeKind::Saline => (BasinStatus::Endorheic, None),
            worldgen::LakeKind::SaltFlat => (BasinStatus::Dry, None),
        };
        basins.push(Basin {
            id: lake.id,
            minimum_cell: lake.minimum_cell,
            minimum_elevation_mm: reference_elevation(lake.minimum_cell as usize),
            cell_count: lake_counts.get(&lake.id).copied().unwrap_or(0),
            spill_cell: lake.spill_cell,
            spill_elevation_mm: spill_elevation,
            water_level_mm: level_mm,
            water_volume_m3: lake.volume_m3.max(0.0).round() as u64,
            inflow_m3_per_year: lake.inflow_m3.max(0.0).round() as u64,
            evaporation_m3_per_year: lake.evaporated_m3.max(0.0).round() as u64,
            outflow_m3_per_year: lake.outflow_m3.max(0.0).round() as u64,
            status,
        });
    }
    let basin_by_id = basins
        .iter()
        .map(|basin| (basin.id, basin))
        .collect::<BTreeMap<_, _>>();
    let mut water_level = Vec::with_capacity(count);
    for cell in 0..count {
        let level = if lake_cells[cell] {
            lake_levels[cell]
        } else if raster.ocean[cell] {
            sea_level
        } else {
            field.elevations_mm[cell].max(sea_level)
        };
        water_level.push(level);
    }
    let island_components = islands;
    let mut island_id = vec![u32::MAX; count];
    let mut watershed_id = vec![u32::MAX; count];
    let mut shelf_cells = vec![false; count];
    for cell in 0..count {
        let source = raster.source_cell[cell] as usize;
        if !raster.ocean[cell] {
            island_id[cell] = island_components[source];
            if roots[source] != u32::MAX {
                watershed_id[cell] = roots[source];
            }
        }
        if raster.ocean[cell] {
            let depth = sea_level.saturating_sub(field.elevations_mm[cell]).max(0);
            let source_is_ocean = world.ocean.get(source).copied().unwrap_or(1) == 1;
            let continental = source_is_ocean && world.crust.get(source).copied().unwrap_or(0) == 1;
            shelf_cells[cell] = continental || (source_is_ocean && depth <= MIN_SHELF_DEPTH_MM);
        }
    }
    let slope = slope_ppm(field);
    let hillshade_ppm = (0..count).map(|cell| hillshade(field, cell)).collect();
    let bathymetry = field
        .elevations_mm
        .iter()
        .map(|value| sea_level.saturating_sub(*value).max(0))
        .collect::<Vec<_>>();
    let river_order = river_order(world, cancelled)?;
    let mut rivers = Vec::with_capacity(world.hydrology.rivers.len());
    let mut river_coordinates = Vec::with_capacity(world.hydrology.rivers.len());
    for (index, river) in world.hydrology.rivers.iter().enumerate() {
        let Some(first) = river.cells.first().copied() else {
            continue;
        };
        let Some(last) = river.cells.last().copied() else {
            continue;
        };
        let destination = match river.end {
            worldgen::RiverEnd::Ocean => RiverDestination::Ocean,
            worldgen::RiverEnd::Lake => {
                let lake = world.hydrology.lake_id[last as usize];
                RiverDestination::Lake(lake)
            }
            worldgen::RiverEnd::Confluence => RiverDestination::Confluence,
        };
        let spill_outlet = match destination {
            RiverDestination::Lake(id) => basin_by_id
                .get(&id)
                .is_some_and(|basin| basin.outflow_m3_per_year > 0),
            _ => false,
        };
        let coordinates = river
            .cells
            .iter()
            .map(|cell| {
                let (lat, lon) = world.cell_lat_lon(*cell);
                [
                    (lon * 1_000_000.0).round() as i32,
                    (lat * 1_000_000.0).round() as i32,
                ]
            })
            .collect::<Vec<_>>();
        rivers.push(RiverSegment {
            id: index as u32,
            source_cell: first,
            mouth_cell: last,
            strahler_order: river
                .cells
                .iter()
                .map(|cell| river_order[*cell as usize])
                .max()
                .unwrap_or(1)
                .max(1),
            destination,
            spill_outlet,
            coordinate_count: river.cells.len() as u32,
        });
        river_coordinates.push(coordinates);
    }
    let land_mask = raster.ocean.iter().map(|ocean| !*ocean).collect::<Vec<_>>();
    let ice_mask = raster
        .ice_cover
        .iter()
        .map(|ice| *ice != 0)
        .collect::<Vec<_>>();
    let coastline = || {
        contours::isolines_at_with_cancel(grid, &field.elevations_mm, sea_level, cancelled)
            .map(|paths| contours::segments_from_paths(&paths))
    };
    let lake_polygons = || contours::polygons_from_mask_with_cancel(grid, &lake_cells, cancelled);
    let land_polygons = || contours::polygons_from_mask_with_cancel(grid, &land_mask, cancelled);
    let ocean_polygons =
        || contours::polygons_from_mask_with_cancel(grid, &raster.ocean, cancelled);
    let shelf_polygons = || contours::polygons_from_mask_with_cancel(grid, &shelf_cells, cancelled);
    let ice_polygons = || contours::polygons_from_mask_with_cancel(grid, &ice_mask, cancelled);
    let bathymetry_contours = || bathymetry_contours(field, &raster.ocean, cancelled);
    let (
        ((coastline_segments, lake_polygons), (land_polygons, ocean_polygons)),
        ((shelf_polygons, ice_polygons), bathymetry_contours),
    ) = rayon::join(
        || {
            rayon::join(
                || rayon::join(coastline, lake_polygons),
                || rayon::join(land_polygons, ocean_polygons),
            )
        },
        || {
            rayon::join(
                || rayon::join(shelf_polygons, ice_polygons),
                bathymetry_contours,
            )
        },
    );
    let coastline_segments = coastline_segments?;
    let lake_polygons = lake_polygons?;
    let land_polygons = land_polygons?;
    let ocean_polygons = ocean_polygons?;
    let shelf_polygons = shelf_polygons?;
    let ice_polygons = ice_polygons?;
    let bathymetry_contours = bathymetry_contours?;
    if cancelled() {
        return Err(PhysicalError::Cancelled);
    }
    let mut watershed_groups: BTreeMap<u32, Vec<usize>> = BTreeMap::new();
    let mut island_groups: BTreeMap<u32, Vec<usize>> = BTreeMap::new();
    for cell in 0..count {
        if watershed_id[cell] != u32::MAX {
            watershed_groups
                .entry(watershed_id[cell])
                .or_default()
                .push(cell);
        }
        if island_id[cell] != u32::MAX {
            island_groups.entry(island_id[cell]).or_default().push(cell);
        }
    }
    let watershed_groups = watershed_groups.values().collect::<Vec<_>>();
    let island_groups = island_groups.values().collect::<Vec<_>>();
    let polygon_batch = |groups: &[&Vec<usize>]| -> Result<Vec<Vec<Vec<[i32; 2]>>>, PhysicalError> {
        groups
            .par_iter()
            .map(|cells| {
                contours::polygons_for_sparse_cells_with_cancel(grid, cells, cancelled)
                    .map(|polygons| polygons.into_iter().flatten().collect())
            })
            .collect()
    };
    let mut watershed_polygons = Vec::with_capacity(watershed_groups.len());
    for chunk in watershed_groups.chunks(16) {
        if cancelled() {
            return Err(PhysicalError::Cancelled);
        }
        watershed_polygons.extend(polygon_batch(chunk)?);
    }
    let mut island_polygons = Vec::with_capacity(island_groups.len());
    for chunk in island_groups.chunks(16) {
        if cancelled() {
            return Err(PhysicalError::Cancelled);
        }
        island_polygons.extend(polygon_batch(chunk)?);
    }
    if cancelled() {
        return Err(PhysicalError::Cancelled);
    }
    let lake_count = basins.len() as u32;
    let metrics = HydrologyMetrics {
        lake_count,
        river_count: rivers.len() as u32,
        watershed_count: watershed_polygons.len() as u32,
        coastline_segment_count: coastline_segments.len() as u32,
        land_polygon_count: land_polygons.len() as u32,
        ocean_polygon_count: ocean_polygons.len() as u32,
        shelf_cell_count: shelf_cells.iter().filter(|value| **value).count() as u32,
        bathymetry_contour_count: bathymetry_contours.len() as u32,
        island_count: island_groups.len() as u32,
    };
    let hydrology = HydrologyField {
        grid,
        derivation_version: HYDROLOGY_DERIVATION_VERSION,
        sea_level_mm: sea_level,
        water_level_mm: water_level,
        lake_level_mm: lake_levels,
        slope_ppm: slope,
        hillshade_ppm,
        bathymetry_mm: bathymetry,
        watershed_id,
        basin_by_cell,
        lake_cells,
        ice_cells: ice_mask,
        shelf_cells,
        island_id,
        basins,
        rivers,
        river_coordinates,
        coastline_segments,
        lake_polygons,
        watershed_polygons,
        land_polygons,
        ocean_polygons,
        shelf_polygons,
        island_polygons,
        ice_polygons,
        bathymetry_contours,
        metrics,
    };
    hydrology.validate(field)?;
    Ok(hydrology)
}

pub(crate) fn map_engine_error(error: worldgen::WorldError, source: bool) -> PhysicalError {
    match error {
        worldgen::WorldError::Cancelled => PhysicalError::Cancelled,
        worldgen::WorldError::InvalidSettings(message) => {
            if source {
                PhysicalError::coded(PhysicalErrorCode::SourceInvalid, message)
            } else {
                PhysicalError::InvalidSettings(message)
            }
        }
        worldgen::WorldError::Internal(message) => {
            if source {
                PhysicalError::coded(PhysicalErrorCode::SourceInvalid, message)
            } else {
                PhysicalError::Validation(message)
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::engine::{self, WorldPreset};
    use crate::planetary::PlanetaryConfiguration;
    use crate::NoopProgress;

    fn generated(resolution: u32) -> engine::Products {
        let settings = engine::Settings::from_parts(
            831_429,
            WorldPreset::Earthlike,
            resolution,
            6_371_000,
            290_000,
            PlanetaryConfiguration::earth_like(),
        );
        engine::generate(settings, &mut NoopProgress).unwrap()
    }

    #[test]
    fn engine_products_have_view_shapes_and_engine_ranges() {
        let products = generated(32);
        let view = products.view();
        let climate = products.climate();
        let hydrology = products.hydrology();
        let hazards = products.hazards();
        let expected = view.grid.sample_count();
        climate.validate().unwrap();
        hydrology.validate(view).unwrap();
        hazards.validate(view.grid).unwrap();
        assert_eq!(hydrology.sea_level_mm, 0);
        assert_eq!(view.sea_level_mm, 0);
        assert!(climate.biome_class.iter().all(|value| *value < 26));
        assert!(hydrology
            .rivers
            .iter()
            .all(|river| river.coordinate_count as usize
                == hydrology.river_coordinates[river.id as usize].len()));
        let canonical_cells = 6 * products.resolution() * products.resolution();
        assert!(hydrology.basins.iter().all(
            |basin| basin.minimum_cell < canonical_cells && basin.spill_cell < canonical_cells
        ));
        assert_eq!(
            hazards.volcanic_sources.len() as u32,
            hazards.metrics.volcanic_source_count
        );
        assert_eq!(climate.storm_suitability_ppm.len(), expected);
        assert_eq!(climate.storm_track_ppm.len(), expected);
        assert_eq!(climate.storm_intensity_ppm.len(), expected);
    }

    #[test]
    fn hazard_unit_conversions_are_explicit_and_bounded() {
        assert_eq!(hazard_ppm(0), 0);
        assert_eq!(hazard_ppm(255), 1_000_000);
        assert_eq!(hazard_ppm(128), 501_960);
        assert_eq!(centi_celsius(12.345), 1_235);
        assert_eq!(centi_celsius(-0.004), 0);
        assert_eq!(millimetres(12.6), 13);
        assert_eq!(milli_units(1.2345), 1_235);
        assert_eq!(milli_units(-1.2345), -1_235);
        assert_eq!(fraction_ppm(0.25), 250_000);
        assert_eq!(fraction_ppm(1.5), 1_000_000);
        assert_eq!(fraction_ppm(-1.0), 0);
        let one_km2 = 1_000_000.0;
        let m5 = 2.0f32;
        let m4 = earthquake_rate_nano(m5, one_km2);
        let expected = (f64::from(m5) * 10f64.powf(0.9) * 1_000_000_000.0).round() as u64;
        assert_eq!(m4, expected);
        let half_area = earthquake_rate_nano(m5, one_km2 / 2.0);
        assert_eq!(half_area, (m4 as f64 / 2.0).round() as u64);
        assert_eq!(rate_per_million_years_ppm(1_000_000_000), 1_000_000);
        assert_eq!(rate_per_million_years_ppm(1_000_000), 1_000);
        assert_eq!(rate_per_million_years_ppm(u64::MAX), 1_000_000);
    }

    #[test]
    fn volcanic_view_rates_sum_the_engine_source_mass() {
        let products = generated(32);
        let hazards = products.hazards();
        let view_sum = hazards
            .volcanic_annual_rate_nano
            .iter()
            .copied()
            .fold(0u64, u64::saturating_add);
        assert_eq!(view_sum, hazards.metrics.volcanic_rate_mass_nano);
    }

    #[test]
    fn volcano_sources_land_on_their_own_latitude_rows() {
        let products = generated(32);
        let hazards = products.hazards();
        let grid = products.view().grid;
        let cube =
            worldgen::CubeSphere::new(products.resolution(), grid.radius_metres as f64).unwrap();
        let row_height = 180.0 / f64::from(grid.height);
        for source in &hazards.volcanic_sources {
            let (lat, lon) = cube.lat_lon(source.cell);
            let cell = view_cell_for_lat_lon(grid, lat.to_degrees(), lon.to_degrees());
            let row = cell / grid.width as usize;
            let center_lat = -90.0 + 180.0 * (row as f64 + 0.5) / f64::from(grid.height);
            assert!(
                (center_lat - lat.to_degrees()).abs() <= row_height,
                "source {} at {:.2}° landed at {:.2}°",
                source.stable_id,
                lat.to_degrees(),
                center_lat
            );
            assert!(
                hazards.volcanic_annual_rate_nano[cell] >= source.eruptions_per_model_year_nano,
                "source {} rate is not in its latitude row",
                source.stable_id
            );
        }
    }

    #[test]
    fn river_strahler_uses_the_river_network_not_hillslopes() {
        let receiver = vec![2u32, 2, 3, 3];
        let rivers = vec![
            worldgen::RiverSegment {
                cells: vec![0, 2],
                end: worldgen::RiverEnd::Confluence,
                max_discharge_m3s: 1.0,
            },
            worldgen::RiverSegment {
                cells: vec![1, 2],
                end: worldgen::RiverEnd::Confluence,
                max_discharge_m3s: 1.0,
            },
            worldgen::RiverSegment {
                cells: vec![2, 3],
                end: worldgen::RiverEnd::Ocean,
                max_discharge_m3s: 1.0,
            },
        ];
        let orders = river_strahler_orders(&receiver, &rivers, &|| false).unwrap();
        assert_eq!(orders[0], 1);
        assert_eq!(orders[1], 1);
        assert_eq!(orders[2], 2);
        assert_eq!(orders[3], 0);
    }

    #[test]
    fn generated_river_orders_are_channel_orders() {
        let products = generated(64);
        let hydrology = products.hydrology();
        let max = hydrology
            .rivers
            .iter()
            .map(|river| river.strahler_order)
            .max()
            .unwrap_or(0);
        assert!(hydrology
            .rivers
            .iter()
            .all(|river| river.strahler_order >= 1));
        assert!(max <= 16, "unexpected Strahler order {max}");
        assert!(
            hydrology
                .rivers
                .iter()
                .any(|river| river.strahler_order >= 2),
            "a generated river network should contain a junction of two order-1 channels"
        );
    }

    #[test]
    fn divergence_uses_the_spherical_latitude_factor() {
        let grid = Grid::new(16, 8, 6_371_000).unwrap();
        let count = grid.sample_count();
        let mut east = vec![0i32; count];
        for (cell, value) in east.iter_mut().enumerate() {
            let (_, col) = grid.row_col(cell);
            *value = col as i32 * 1_000;
        }
        let north = vec![0i32; count];
        let diverging = divergence(grid, &east, &north);
        let equator_row = 3usize;
        let polar_row = 0usize;
        let equator = diverging[equator_row * grid.width as usize + 8].unsigned_abs();
        let polar = diverging[polar_row * grid.width as usize + 8].unsigned_abs();
        assert!(polar > equator, "polar {polar}, equator {equator}");
        let uniform = divergence(grid, &vec![1_000; count], &vec![0; count]);
        assert!(uniform.iter().all(|value| value == &0));
    }

    #[test]
    fn river_coordinates_use_canonical_degrees_not_view_edges() {
        let products = generated(32);
        let hydrology = products.hydrology();
        for (river, coordinates) in hydrology.rivers.iter().zip(&hydrology.river_coordinates) {
            assert_eq!(river.coordinate_count as usize, coordinates.len());
            for [lon, lat] in coordinates {
                assert!((-180_000_000..=180_000_000).contains(lon));
                assert!((-90_000_000..=90_000_000).contains(lat));
            }
        }
    }
}
